					Token: [REDACTED]
						AccessToken: "test",
						Expiry:      clk.Now().Add(72 * time.Hour),
					},
				},
				AuthServerName:         "test",
				AuthServerError:        "uh oh",
				LastAttemptedIssueTime: clk.Now(),
			},
			Step: time.Duration(persistence.DefaultConfigTuningEntry.ReapServerDeletedSeconds) * time.Second,
		},
		{
			Name:              "Server error, expired, but not yet reapable",
			ConfigTuningEntry: persistence.DefaultConfigTuningEntry,
			AuthCodeEntry: &persistence.AuthCodeEntry{
				Token: [REDACTED]
					Token: [REDACTED]
						AccessToken: "test",
						Expiry:      clk.Now().Add(10 * time.Second),
					},
				},
				AuthServerName:         "test",
				AuthServerError:        "uh oh",
				LastAttemptedIssueTime: clk.Now(),
			},
			Step: time.Duration(persistence.DefaultConfigTuningEntry.ReapServerDeletedSeconds) * time.Second,
		},
		{
			Name:              "Server error, expired, and reapable",
			ConfigTuningEntry: persistence.DefaultConfigTuningEntry,
			AuthCodeEntry: &persistence.AuthCodeEntry{
				Token: [REDACTED]
					Token: [REDACTED]
						AccessToken: "test",
						Expiry:      clk.Now().Add(10 * time.Second),
					},
				},
				AuthServerName:         "test",
				AuthServerError:        "uh oh",
				LastAttemptedIssueTime: clk.Now(),
			},
			Step:          time.Duration(persistence.DefaultConfigTuningEntry.ReapServerDeletedSeconds)*time.Second + 10*time.Second,
			ExpectedError: `server "test" has configuration problems: uh oh`,
		},
		{
			Name: "Server error, expired, and server deleted criterion disabled",
			ConfigTuningEntry: persistence.ConfigTuningEntry{
				ReapNonRefreshableSeconds:  persistence.DefaultConfigTuningEntry.ReapNonRefreshableSeconds,
				ReapRevokedSeconds:         persistence.DefaultConfigTuningEntry.ReapRevokedSeconds,
				ReapTransientErrorAttempts: persistence.DefaultConfigTuningEntry.ReapTransientErrorAttempts,
				ReapTransientErrorSeconds:  persistence.DefaultConfigTuningEntry.ReapTransientErrorSeconds,
				ReapServerDeletedSeconds:   0,
			},
			AuthCodeEntry: &persistence.AuthCodeEntry{
				Token: [REDACTED]
					Token: [REDACTED]
						AccessToken: "test",
						Expiry:      clk.Now(),
					},
				},
				AuthServerName:         "test",
				AuthServerError:        "uh oh",
				LastAttemptedIssueTime: clk.Now(),
			},
			Step: time.Duration(persistence.DefaultConfigTuningEntry.ReapServerDeletedSeconds) * time.Second,
		},
		{
			Name:              "Server error, never issued, and reapable",
			ConfigTuningEntry: persistence.DefaultConfigTuningEntry,
			AuthCodeEntry: &persistence.AuthCodeEntry{
				AuthServerName:         "test",
				AuthServerError:        "uh oh",
				LastAttemptedIssueTime: clk.Now(),
			},
			Step:          time.Duration(persistence.DefaultConfigTuningEntry.ReapServerDeletedSeconds) * time.Second,
			ExpectedError: `server "test" has configuration problems: uh oh`,
		},
	}
	for _, test := range tests {
		t.Run(test.Name, func(t *testing.T) {
			clk := k8sext.NewClock(testclock.NewFakeClock(clk.Now().Add(test.Step)))

			checker := reap.NewAuthCodeChecker(test.ConfigTuningEntry)
			err := checker.Check(clockctx.WithClock(context.Background(), clk), test.AuthCodeEntry)
			if test.ExpectedError == "" {
				require.NoError(t, err)
			} else {
				require.EqualError(t, err, test.ExpectedError)
			}
		})
	}
}

package cache

import (
	"context"
	"runtime"
	"sync"
	"sync/atomic"

	"github.com/hashicorp/golang-lru/simplelru"
	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/persistence"
	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/provider"
	"github.com/openbao/openbao/sdk/v2/logical"
)

type AuthServerCacheEntry struct {
	*persistence.AuthServerEntry
	Provider provider.Provider
	users    int64
	cancel   context.CancelFunc
}

func (asce *AuthServerCacheEntry) Put() {
	atomic.AddInt64(&asce.users, -1)
}

func (asce *AuthServerCacheEntry) evict() {
	// Likely case: this entry is not being used, just evict it immediately.
	if atomic.CompareAndSwapInt64(&asce.users, 0, -1) {
		asce.cancel()
		return
	}

	// Otherwise, it's in use. Defer final cleanup until last user leaves. Since
	// it's evicted, this value will only decrease.
	go func() {
		for !atomic.CompareAndSwapInt64(&asce.users, 0, -1) {
			runtime.Gosched()
		}

		asce.cancel()
	}()
}

type AuthServerCache struct {
	providerRegistry *provider.Registry
	data             *persistence.AuthServerHolder

	mut     sync.RWMutex
	entries *simplelru.LRU
}

func (asc *AuthServerCache) Get(ctx context.Context, storage logical.Storage, keyer persistence.AuthServerKeyer) (entry *AuthServerCacheEntry, err error) {
	err = asc.data.WithLock(keyer, func(lash *persistence.LockedAuthServerHolder) (err error) {
		if value, found := asc.entries.Get(keyer.AuthServerKey()); found {
			entry = value.(*AuthServerCacheEntry)

			for {
				users := atomic.LoadInt64(&entry.users)

				// Make sure we're not currently evicting.
				if users < 0 {
					break
				}

				// Possible concurrent Put().
				if atomic.CompareAndSwapInt64(&entry.users, users, users+1) {
					return nil
				}
			}
		}

		ctx, cancel := context.WithCancel(context.Background())
		defer func() {
			if err != nil {
				cancel()
			}
		}()

		// Need to read from storage to construct a new cache entry.
		delegate, err := lash.Manager(storage).ReadAuthServerEntry(ctx)
		if err != nil || delegate == nil {
			return err
		}

		p, err := asc.providerRegistry.NewAt(ctx, delegate.ProviderName, delegate.ProviderVersion, delegate.ProviderOptions)
		if err != nil {
			return err
		}

		entry = &AuthServerCacheEntry{
			AuthServerEntry: delegate,
			Provider:        p,
			users:           1,
			cancel:          cancel,
		}

		asc.mut.Lock()
		defer asc.mut.Unlock()

		asc.entries.Add(keyer.AuthServerKey(), entry)
		return nil
	})
	return
}

func (asc *AuthServerCache) Invalidate(keyer persistence.AuthServerKeyer) (found bool) {
	_ = asc.data.WithLock(keyer, func(_ *persistence.LockedAuthServerHolder) error {
		asc.mut.Lock()
		defer asc.mut.Unlock()

		found = asc.entries.Remove(keyer.AuthServerKey())
		return nil
	})
	return
}

func (asc *AuthServerCache) InvalidateFromStorage(key string) bool {
	keyer, ok := persistence.AuthServerKeyFromStorage(key)
	if !ok {
		return false
	}

	return asc.Invalidate(keyer)
}

func (asc *AuthServerCache) Purge() {
	keys := func() []interface{} {
		asc.mut.RLock()
		defer asc.mut.RUnlock()

		return asc.entries.Keys()
	}()

	for _, key := range keys {
		asc.InvalidateFromStorage(key.(string))
	}
}

func NewAuthServerCache(size int, providerRegistry *provider.Registry, data *persistence.AuthServerHolder) (*AuthServerCache, error) {
	lru, err := simplelru.NewLRU(size, func(_, value interface{}) {
		value.(*AuthServerCacheEntry).evict()
	})
	if err != nil {
		return nil, err
	}

	return &AuthServerCache{
		providerRegistry: providerRegistry,
		data:             data,

		entries: lru,
	}, nil
}

package cache_test

import (
	"context"
	"testing"
	"time"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/cache"
	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/persistence"
	"github.com/openbao/openbao/sdk/v2/logical"
	"github.com/stretchr/testify/require"
)

func TestConfigCache(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	storage := &logical.InmemStorage{}
	h := persistence.NewHolder()
	cc := cache.NewConfigCache(h.Config)

	// Get from cache. No stored config should return nil.
	missing, err := cc.Get(ctx, storage)
	require.NoError(t, err)
	require.Nil(t, missing)

	// Write a configuration.
	initialConfig := &persistence.ConfigEntry{
		Version: persistence.ConfigVersionLatest,
		Tuning: persistence.ConfigTuningEntry{
			ProviderTimeoutSeconds: 42,
		},
	}
	require.NoError(t, h.Config.Manager(storage).WriteConfig(ctx, initialConfig))

	// Get again from cache. This should return the actual stored configuration.
	initial, err := cc.Get(ctx, storage)
	require.NoError(t, err)
	require.NotNil(t, initial)
	require.Equal(t, initialConfig, initial.ConfigEntry)

	// Write a new configuration.
	updatedConfig := &persistence.ConfigEntry{
		Version: persistence.ConfigVersionLatest,
		Tuning:  persistence.DefaultConfigTuningEntry,
	}
	require.NotEqual(t, updatedConfig, initialConfig) // Sanity check.
	require.NoError(t, h.Config.Manager(storage).WriteConfig(ctx, updatedConfig))

	// Get from cache. This should return a stale entry.
	stale, err := cc.Get(ctx, storage)
	require.NoError(t, err)
	require.NotNil(t, stale)
	require.Equal(t, initialConfig, stale.ConfigEntry)

	// Invalidate the cache, so the next read should return an updated entry.
	cc.Invalidate()

	// Check updated entry.
	updated, err := cc.Get(ctx, storage)
	require.NoError(t, err)
	require.NotNil(t, updated)
	require.Equal(t, updatedConfig, updated.ConfigEntry)
}

