package persistence

import (
	"context"
	"crypto/sha1"
	"fmt"
	"time"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/provider"
	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/vaultext"
	"github.com/openbao/openbao/sdk/v2/helper/locksutil"
	"github.com/openbao/openbao/sdk/v2/logical"
	"github.com/puppetlabs/leg/timeutil/pkg/clockctx"
	"golang.org/x/oauth2"
)

const (
	authCodeKeyPrefix   = "creds/"
	deviceAuthKeyPrefix = "devices/"
)

type AuthCodeKeyer interface {
	// AuthCodeKey returns the storage key for storing AuthCodeEntry objects.
	AuthCodeKey() string

	// DeviceAuthKey returns the storage key for storing DeviceAuthEntry
	// objects.
	DeviceAuthKey() string
}

type AuthCodeEntry struct {
	// We embed a *provider.Token as the base type. This ensures compatibility
	// and keeps storage size reasonable because this will be the default
	// configuration.
	*provider.Token `json:",inline"`

	// AuthServerName is the authorization server we should use to handle this
	// entry.
	AuthServerName string `json:"auth_server_name"`

	// MaximumExpirySeconds caps issued auth tokens to a desired lifetime.
	MaximumExpirySeconds int `json:"maximum_expiry_seconds,omitempty"`

	// LastIssueTime is the most recent time a token was successfully issued.
	LastIssueTime time.Time `json:"last_issue_time,omitempty"`

	// AuthServerError indicates that the actual backing server and provider
	// could not be acquired to make this token request.
	AuthServerError string `json:"auth_server_error,omitempty"`

	// UserError is used to store a permanent error that indicates the end of
	// this token's usable lifespan.
	UserError string `json:"user_error,omitempty"`

	// TransientErrorsSinceLastIssue is a counter of the number of transient
	// errors encountered since the last time the token was successfully issued
	// (either originally or by refresh).
	TransientErrorsSinceLastIssue int `json:"transient_errors_since_last_issue,omitempty"`

	// If TransientErrorsSinceLastIssue > 0, this holds the last transient error
	// encountered to include as a warning (if the token is still valid) or
	// error on the response.
	LastTransientError string `json:"last_transient_error,omitempty"`

	// If the most recent exchange did not succeed, this holds the time that
	// exchange occurred.
	LastAttemptedIssueTime time.Time `json:"last_attempted_issue_time,omitempty"`

	// Cache of successfully exchanged tokens
	ExchangedTokens map[string]*oauth2.Token `json:"exchanged_tokens"`
}

func (ace *AuthCodeEntry) SetToken(ctx context.Context, tok *provider.Token) {
	ace.Token = tok
	ace.LastIssueTime = clockctx.Clock(ctx).Now()
	if ace.MaximumExpirySeconds != 0 {
		maximumExpiry := ace.LastIssueTime.Add(time.Duration(ace.MaximumExpirySeconds) * time.Second)
		if ace.Expiry.IsZero() || ace.Expiry.After(maximumExpiry) {
			ace.Expiry = maximumExpiry
		}
	}
	ace.AuthServerError = ""
	ace.UserError = ""
	ace.TransientErrorsSinceLastIssue = 0
	ace.LastTransientError = ""
	ace.LastAttemptedIssueTime = time.Time{}
}

func (ace *AuthCodeEntry) SetAuthServerError(ctx context.Context, err string) {
	ace.AuthServerError = err
	ace.LastAttemptedIssueTime = clockctx.Clock(ctx).Now()
}

func (ace *AuthCodeEntry) SetUserError(ctx context.Context, err string) {
	ace.AuthServerError = ""
	ace.UserError = err
	ace.LastAttemptedIssueTime = clockctx.Clock(ctx).Now()
}

func (ace *AuthCodeEntry) SetTransientError(ctx context.Context, err string) {
	ace.AuthServerError = ""
	ace.TransientErrorsSinceLastIssue++
	ace.LastTransientError = err
	ace.LastAttemptedIssueTime = clockctx.Clock(ctx).Now()
}

// TokenIssued indicates whether a token has been issued at all.
//
// For certain grant types, like device code flow, we may not have an access
// token yet. In that case, we must wait for a polling process to update this
// value. A temporary error will be returned.
func (ace *AuthCodeEntry) TokenIssued() bool {
	return ace.Token != nil && ace.AccessToken != ""
}

type DeviceAuthEntry struct {
	DeviceCode             string            `json:"device_code"`
	Interval               int32             `json:"interval"`
	LastAttemptedIssueTime time.Time         `json:"last_attempted_issue_time"`
	ProviderOptions        map[string]string `json:"provider_options"`
}

func (dae *DeviceAuthEntry) ShouldPoll(ctx context.Context) bool {
	return dae.LastAttemptedIssueTime.Add(time.Duration(dae.Interval) * time.Second).Before(clockctx.Clock(ctx).Now())
}

type AuthCodeKey string

var _ AuthCodeKeyer = AuthCodeKey("")

func (ack AuthCodeKey) AuthCodeKey() string   { return authCodeKeyPrefix + string(ack) }
func (ack AuthCodeKey) DeviceAuthKey() string { return deviceAuthKeyPrefix + string(ack) }

func AuthCodeName(name string) AuthCodeKeyer {
	hash := sha1.Sum([]byte(name))
	first, second, rest := hash[:2], hash[2:4], hash[4:]
	return AuthCodeKey(fmt.Sprintf("%x/%x/%x", first, second, rest))
}

type LockedAuthCodeManager struct {
	storage logical.Storage
	keyer   AuthCodeKeyer
}

func (lacm *LockedAuthCodeManager) ReadAuthCodeEntry(ctx context.Context) (*AuthCodeEntry, error) {
	se, err := lacm.storage.Get(ctx, lacm.keyer.AuthCodeKey())
	if err != nil {
		return nil, err
	} else if se == nil {
		return nil, nil
	}

	entry := &AuthCodeEntry{}
	if err := se.DecodeJSON(entry); err != nil {
		return nil, err
	}

	// UPGRADING (v2): Set the server name to the default legacy server if it is
	// not present here.
	if entry.AuthServerName == "" {
		entry.AuthServerName = LegacyAuthServerName
	}

	return entry, nil
}

func (lacm *LockedAuthCodeManager) ReadDeviceAuthEntry(ctx context.Context) (*DeviceAuthEntry, error) {
	se, err := lacm.storage.Get(ctx, lacm.keyer.DeviceAuthKey())
	if err != nil {
		return nil, err
	} else if se == nil {
		return nil, nil
	}

	entry := &DeviceAuthEntry{}
	if err := se.DecodeJSON(entry); err != nil {
		return nil, err
	}

	return entry, nil
}

func (lacm *LockedAuthCodeManager) WriteAuthCodeEntry(ctx context.Context, entry *AuthCodeEntry) error {
	se, err := logical.StorageEntryJSON(lacm.keyer.AuthCodeKey(), entry)
	if err != nil {
		return err
	}

	return lacm.storage.Put(ctx, se)
}

func (lacm *LockedAuthCodeManager) WriteDeviceAuthEntry(ctx context.Context, entry *DeviceAuthEntry) error {
	se, err := logical.StorageEntryJSON(lacm.keyer.DeviceAuthKey(), entry)
	if err != nil {
		return err
	}

	return lacm.storage.Put(ctx, se)
}

func (lacm *LockedAuthCodeManager) DeleteAuthCodeEntry(ctx context.Context) error {
	return lacm.storage.Delete(ctx, lacm.keyer.AuthCodeKey())
}

func (lacm *LockedAuthCodeManager) DeleteDeviceAuthEntry(ctx context.Context) error {
	return lacm.storage.Delete(ctx, lacm.keyer.DeviceAuthKey())
}

type LockedAuthCodeHolder struct {
	keyer AuthCodeKeyer
}

func (lach *LockedAuthCodeHolder) Manager(storage logical.Storage) *LockedAuthCodeManager {
	return &LockedAuthCodeManager{
		storage: storage,
		keyer:   lach.keyer,
	}
}

type AuthCodeLocker interface {
	WithLock(AuthCodeKeyer, func(*LockedAuthCodeHolder) error) error
}

type AuthCodeManager struct {
	storage logical.Storage
	locker  AuthCodeLocker
}

func (acm *AuthCodeManager) ReadAuthCodeEntry(ctx context.Context, keyer AuthCodeKeyer) (*AuthCodeEntry, error) {
	var entry *AuthCodeEntry
	err := acm.locker.WithLock(keyer, func(lach *LockedAuthCodeHolder) (err error) {
		entry, err = lach.Manager(acm.storage).ReadAuthCodeEntry(ctx)
		return
	})
	return entry, err
}

func (acm *AuthCodeManager) ReadDeviceAuthEntry(ctx context.Context, keyer AuthCodeKeyer) (*DeviceAuthEntry, error) {
	var entry *DeviceAuthEntry
	err := acm.locker.WithLock(keyer, func(lach *LockedAuthCodeHolder) (err error) {
		entry, err = lach.Manager(acm.storage).ReadDeviceAuthEntry(ctx)
		return
	})
	return entry, err
}

func (acm *AuthCodeManager) WriteAuthCodeEntry(ctx context.Context, keyer AuthCodeKeyer, entry *AuthCodeEntry) error {
	return acm.locker.WithLock(keyer, func(lach *LockedAuthCodeHolder) error {
		return lach.Manager(acm.storage).WriteAuthCodeEntry(ctx, entry)
	})
}

func (acm *AuthCodeManager) WriteDeviceAuthEntry(ctx context.Context, keyer AuthCodeKeyer, entry *DeviceAuthEntry) error {
	return acm.locker.WithLock(keyer, func(lach *LockedAuthCodeHolder) error {
		return lach.Manager(acm.storage).WriteDeviceAuthEntry(ctx, entry)
	})
}

func (acm *AuthCodeManager) DeleteAuthCodeEntry(ctx context.Context, keyer AuthCodeKeyer) error {
	return acm.locker.WithLock(keyer, func(lach *LockedAuthCodeHolder) error {
		return lach.Manager(acm.storage).DeleteAuthCodeEntry(ctx)
	})
}

func (acm *AuthCodeManager) DeleteDeviceAuthEntry(ctx context.Context, keyer AuthCodeKeyer) error {
	return acm.locker.WithLock(keyer, func(lach *LockedAuthCodeHolder) error {
		return lach.Manager(acm.storage).DeleteDeviceAuthEntry(ctx)
	})
}

func (acm *AuthCodeManager) ForEachAuthCodeKey(ctx context.Context, fn func(AuthCodeKeyer) error) error {
	view := logical.NewStorageView(acm.storage, authCodeKeyPrefix)
	return vaultext.ScanView(ctx, view, func(path string) error { return fn(AuthCodeKey(path)) })
}

func (acm *AuthCodeManager) ForEachDeviceAuthKey(ctx context.Context, fn func(AuthCodeKeyer) error) error {
	view := logical.NewStorageView(acm.storage, deviceAuthKeyPrefix)
	return vaultext.ScanView(ctx, view, func(path string) error { return fn(AuthCodeKey(path)) })
}

type AuthCodeHolder struct {
	locks []*locksutil.LockEntry
}

func (ach *AuthCodeHolder) WithLock(keyer AuthCodeKeyer, fn func(*LockedAuthCodeHolder) error) error {
	lock := locksutil.LockForKey(ach.locks, keyer.AuthCodeKey())
	lock.Lock()
	defer lock.Unlock()

	return fn(&LockedAuthCodeHolder{
		keyer: keyer,
	})
}

func (ach *AuthCodeHolder) Manager(storage logical.Storage) *AuthCodeManager {
	return &AuthCodeManager{
		storage: storage,
		locker:  ach,
	}
}

package persistence

import (
	"context"
	"crypto/sha256"
	"fmt"
	"strings"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/vaultext"
	"github.com/openbao/openbao/sdk/v2/helper/locksutil"
	"github.com/openbao/openbao/sdk/v2/logical"
)

const (
	authServerKeyPrefix = "servers/"
)

type AuthServerKeyer interface {
	// AuthServerKey returns the storage key for storing AuthServerEntry
	// objects.
	AuthServerKey() string
}

type AuthServerEntry struct {
	Name string `json:"name"`

	ClientID        string            `json:"client_id"`
	ClientSecrets   []string          `json:"client_secrets"`
	AuthURLParams   map[string]string `json:"auth_url_params"`
	ProviderName    string            `json:"provider_name"`
	ProviderVersion int               `json:"provider_version"`
	ProviderOptions map[string]string `json:"provider_options"`
}

// UPGRADING (v2): LegacyAuthServerName is the name of the default server
// created by the v2v3 upgrade.
const LegacyAuthServerName = "legacy"

type AuthServerKey string

var _ AuthServerKeyer = AuthServerKey("")

func (ack AuthServerKey) AuthServerKey() string { return authServerKeyPrefix + string(ack) }

func AuthServerName(name string) AuthServerKeyer {
	hash := sha256.Sum224([]byte(name))
	first, second, rest := hash[:2], hash[2:4], hash[4:]
	return AuthServerKey(fmt.Sprintf("%x/%x/%x", first, second, rest))
}

func AuthServerKeyFromStorage(key string) (AuthServerKeyer, bool) {
	if !strings.HasPrefix(key, authServerKeyPrefix) {
		return nil, false
	}

	return AuthServerKey(key[len(authServerKeyPrefix):]), true
}

type LockedAuthServerManager struct {
	storage logical.Storage
	keyer   AuthServerKeyer
}

func (lasm *LockedAuthServerManager) ReadAuthServerEntry(ctx context.Context) (*AuthServerEntry, error) {
	se, err := lasm.storage.Get(ctx, lasm.keyer.AuthServerKey())
	if err != nil {
		return nil, err
	} else if se == nil {
		return nil, nil
	}

	entry := &AuthServerEntry{}
	if err := se.DecodeJSON(entry); err != nil {
		return nil, err
	}

	// UPGRADING (v3.0.0-beta.{1,2,3,4}): Early v3 versions only supported a
	// single client secret for a server, so we check for it here and copy it
	// into the returned value if necessary.
	var migrating struct {
		ClientSecret string `json:"client_secret"`
	}
	if err := se.DecodeJSON(&migrating); err != nil {
		return nil, err
	}

	if migrating.ClientSecret != "" {
		entry.ClientSecrets = append([]string{migrating.ClientSecret}, entry.ClientSecrets...)
	}

	return entry, nil
}

func (lasm *LockedAuthServerManager) WriteAuthServerEntry(ctx context.Context, entry *AuthServerEntry) error {
	key := lasm.keyer.AuthServerKey()

	// Sanity check: constructing the key from the name specified in the entry
	// must equal the key we're using for this operation.
	if AuthServerName(entry.Name).AuthServerKey() != key {
		return fmt.Errorf("writing authorization server: name %q does not correspond to storage key", entry.Name)
	}

	se, err := logical.StorageEntryJSON(key, entry)
	if err != nil {
		return err
	}

	return lasm.storage.Put(ctx, se)
}

func (lasm *LockedAuthServerManager) DeleteAuthServerEntry(ctx context.Context) error {
	return lasm.storage.Delete(ctx, lasm.keyer.AuthServerKey())
}

type LockedAuthServerHolder struct {
	keyer AuthServerKeyer
}

func (lash *LockedAuthServerHolder) Manager(storage logical.Storage) *LockedAuthServerManager {
	return &LockedAuthServerManager{
		storage: storage,
		keyer:   lash.keyer,
	}
}

type AuthServerLocker interface {
	WithLock(AuthServerKeyer, func(*LockedAuthServerHolder) error) error
}

type AuthServerManager struct {
	storage logical.Storage
	locker  AuthServerLocker
}

func (asm *AuthServerManager) ReadAuthServerEntry(ctx context.Context, keyer AuthServerKeyer) (*AuthServerEntry, error) {
	var entry *AuthServerEntry
	err := asm.locker.WithLock(keyer, func(lash *LockedAuthServerHolder) (err error) {
		entry, err = lash.Manager(asm.storage).ReadAuthServerEntry(ctx)
		return
	})
	return entry, err
}

func (asm *AuthServerManager) WriteAuthServerEntry(ctx context.Context, keyer AuthServerKeyer, entry *AuthServerEntry) error {
	return asm.locker.WithLock(keyer, func(lash *LockedAuthServerHolder) error {
		return lash.Manager(asm.storage).WriteAuthServerEntry(ctx, entry)
	})
}

func (asm *AuthServerManager) DeleteAuthServerEntry(ctx context.Context, keyer AuthServerKeyer) error {
	return asm.locker.WithLock(keyer, func(lash *LockedAuthServerHolder) error {
		return lash.Manager(asm.storage).DeleteAuthServerEntry(ctx)
	})
}

func (asm *AuthServerManager) ForEachAuthServerKey(ctx context.Context, fn func(AuthServerKeyer) error) error {
	view := logical.NewStorageView(asm.storage, authServerKeyPrefix)
	return vaultext.ScanView(ctx, view, func(path string) error { return fn(AuthServerKey(path)) })
}

type AuthServerHolder struct {
	locks []*locksutil.LockEntry
}

func (ash *AuthServerHolder) WithLock(keyer AuthServerKeyer, fn func(*LockedAuthServerHolder) error) error {
	lock := locksutil.LockForKey(ash.locks, keyer.AuthServerKey())
	lock.Lock()
	defer lock.Unlock()

	return fn(&LockedAuthServerHolder{
		keyer: keyer,
	})
}

func (ash *AuthServerHolder) Manager(storage logical.Storage) *AuthServerManager {
	return &AuthServerManager{
		storage: storage,
		locker:  ash,
	}
}

package backend

import (
	"context"
	"encoding/base64"
	"fmt"
	"strings"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/persistence"
	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/provider"
	"github.com/openbao/openbao/sdk/v2/framework"
	"github.com/openbao/openbao/sdk/v2/logical"
)

func (b *backend) authCodeURLUpdateOperation(ctx context.Context, req *logical.Request, data *framework.FieldData) (*logical.Response, error) {
	serverName, err := b.getServerNameOrDefault(ctx, req.Storage, data.Get("server").(string))
	if err != nil {
		return errorResponse(err)
	}

	ops, put, err := b.getProviderOperations(ctx, req.Storage, persistence.AuthServerName(serverName), defaultExpiryDelta)
	if err != nil {
		return errorResponse(fmt.Errorf("server %q has configuration problems: %w", serverName, err))
	}
	defer put()

	resp := &logical.Response{
		Data: make(map[string]interface{}),
	}

	state, ok := data.GetOk("state")
	if !ok {
		rd := make([]byte, 32)
		if _, err := b.GetRandomReader().Read(rd); err != nil {
			return nil, err
		}

		state = base64.RawURLEncoding.EncodeToString(rd)
		resp.Data["state"] = state
	}

	url, ok := ops.AuthCodeURL(
		state.(string),
		provider.WithRedirectURL(data.Get("redirect_url").(string)),
		provider.WithScopes(data.Get("scopes").([]string)),
		provider.WithURLParams(data.Get("auth_url_params").(map[string]string)),
		provider.WithProviderOptions(data.Get("provider_options").(map[string]string)),
	)
	if !ok {
		return logical.ErrorResponse("authorization code URL not available"), nil
	}

	resp.Data["url"] = url

	return resp, nil
}

const (
	AuthCodeURLPath = "auth-code-url"
)

var authCodeURLFields = map[string]*framework.FieldSchema{
	// fields for write operations
	"server": {
		Type:        framework.TypeString,
		Description: "Specifies the name of the server.",
	},
	"auth_url_params": {
		Type:        framework.TypeKVPairs,
		Description: "Specifies the additional query parameters to add to the authorization code URL.",
	},
	"redirect_url": {
		Type:        framework.TypeString,
		Description: "The URL to redirect to after the authorization flow completes.",
	},
	"scopes": {
		Type:        framework.TypeCommaStringSlice,
		Description: "The scopes to request for authorization.",
	},
	"state": {
		Type:        framework.TypeString,
		Description: "Specifies the state to set in the authorization code URL.",
	},
	"provider_options": {
		Type:        framework.TypeKVPairs,
		Description: "Specifies any provider-specific options.",
	},
}

const authCodeURLHelpSynopsis = `
Generates authorization code URLs for a server configuration.
`

const authCodeURLHelpDescription = `
This endpoint merges server configuration data with requested
parameters like a redirect URL and scopes to create an authorization
code URL. The code returned in the response should be written to a
credential endpoint to start managing authentication tokens.
`

func pathAuthCodeURL(b *backend) *framework.Path {
	return &framework.Path{
		Pattern: AuthCodeURLPath + `$`,
		Fields:  authCodeURLFields,
		Operations: map[logical.Operation]framework.OperationHandler{
			logical.UpdateOperation: &framework.PathOperation{
				Callback: b.authCodeURLUpdateOperation,
				Summary:  "Get an initial authorization code URL.",
			},
		},
		HelpSynopsis:    strings.TrimSpace(authCodeURLHelpSynopsis),
		HelpDescription: strings.TrimSpace(authCodeURLHelpDescription),
	}
}

package reap

import (
	"context"
	"fmt"
	"time"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/persistence"
	"github.com/puppetlabs/leg/timeutil/pkg/clockctx"
)

type AuthCodeChecker struct {
	nonRefreshableTTL      time.Duration
	revokedTTL             time.Duration
	transientErrorAttempts int
	transientErrorTTL      time.Duration
	serverDeletedTTL       time.Duration
}

// Check tests whether the given authorization code entry is still valid. If it
// is, it returns nil. Otherwise, it returns an error indicating the reason the
// entry is not valid.
func (acc *AuthCodeChecker) Check(ctx context.Context, entry *persistence.AuthCodeEntry) error {
	now := clockctx.Clock(ctx).Now()

	// We can get an error before we ever actually issue a token, so for the
	// reference time to check, we'll either use the actual expiry or the last
	// attempted issue time.
	getReferenceTime := func() time.Time {
		if entry.TokenIssued() && !entry.Expiry.IsZero() {
			return entry.Expiry
		}
		return entry.LastAttemptedIssueTime
	}

	switch {
	case entry.UserError != "":
		if acc.revokedTTL <= 0 {
			// We will not take action on this token for the revoked
			// criterion.
			return nil
		}

		if getReferenceTime().Add(acc.revokedTTL).After(now) {
			// Not yet ready to be reaped.
			return nil
		}

		return fmt.Errorf("token revoked: %s", entry.UserError)
	case entry.TransientErrorsSinceLastIssue > 0:
		if acc.transientErrorAttempts <= 0 && acc.transientErrorTTL <= 0 {
			// We will not take action on this token for the transient error
			// criteria.
			return nil
		}

		if entry.TransientErrorsSinceLastIssue < acc.transientErrorAttempts {
			// Haven't met the threshold for transient errors yet.
			return nil
		}

		if getReferenceTime().Add(acc.transientErrorTTL).After(now) {
			// Not yet ready to be reaped.
			return nil
		}

		return fmt.Errorf("transient errors exceeded limits, most recently: %s", entry.LastTransientError)
	case entry.AuthServerError != "":
		if acc.serverDeletedTTL <= 0 {
			// We will not take action on this token if its backing server is
			// deleted. Wait for the server to come back.
			return nil
		}

		if getReferenceTime().Add(acc.serverDeletedTTL).After(now) {
			// Not yet ready to be reaped.
			return nil
		}

		return fmt.Errorf("server %q has configuration problems: %s", entry.AuthServerName, entry.AuthServerError)
	case !entry.TokenIssued():
		// Waiting for a token from an external process (e.g., device code
		// auth). Do nothing.
		return nil
	case entry.Expiry.IsZero():
		// Token never expires.
		return nil
	case entry.RefreshToken != "":
		// Token expires, but it has a valid refresh token.
		return nil
	case acc.nonRefreshableTTL <= 0, entry.Expiry.Add(acc.nonRefreshableTTL).After(now):
		// Token expires, but it is not yet ready to be reaped.
		return nil
	default:
		return fmt.Errorf("token expired")
	}
}

func NewAuthCodeChecker(tuning persistence.ConfigTuningEntry) *AuthCodeChecker {
	return &AuthCodeChecker{
		nonRefreshableTTL:      time.Duration(tuning.ReapNonRefreshableSeconds) * time.Second,
		revokedTTL:             time.Duration(tuning.ReapRevokedSeconds) * time.Second,
		transientErrorAttempts: tuning.ReapTransientErrorAttempts,
		transientErrorTTL:      time.Duration(tuning.ReapTransientErrorSeconds) * time.Second,
		serverDeletedTTL:       time.Duration(tuning.ReapServerDeletedSeconds) * time.Second,
	}
}

package backend

import (
	"context"
	"errors"
	"fmt"
	"math"
	"time"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/persistence"
	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/provider"
	"github.com/openbao/openbao/sdk/v2/helper/consts"
	"github.com/openbao/openbao/sdk/v2/logical"
	"github.com/puppetlabs/leg/errmap/pkg/errmap"
	"github.com/puppetlabs/leg/errmap/pkg/errmark"
	"github.com/puppetlabs/leg/scheduler"
	"github.com/puppetlabs/leg/timeutil/pkg/backoff"
	"github.com/puppetlabs/leg/timeutil/pkg/clockctx"
	"github.com/puppetlabs/leg/timeutil/pkg/retry"
	"golang.org/x/oauth2"
)

type refreshProcess struct {
	backend     *backend
	storage     logical.Storage
	keyer       persistence.AuthCodeKeyer
	expiryDelta time.Duration
}

var _ scheduler.Process = &refreshProcess{}

func (rp *refreshProcess) Description() string {
	return fmt.Sprintf("credential refresh (%s)", rp.keyer.AuthCodeKey())
}

func (rp *refreshProcess) Run(ctx context.Context) error {
	_, err := rp.backend.getRefreshCredToken(ctx, rp.storage, rp.keyer, rp.expiryDelta)
	return err
}

type refreshDescriptor struct {
	backend *backend
	storage logical.Storage
}

var _ scheduler.Descriptor = &refreshDescriptor{}

func (rd *refreshDescriptor) Run(ctx context.Context, pc chan<- scheduler.Process) error {
	tuning := persistence.DefaultConfigTuningEntry

	if cfg, err := rd.backend.cache.Config.Get(ctx, rd.storage); err != nil {
		return err
	} else if cfg != nil {
		tuning = cfg.Tuning
	}

	if tuning.RefreshCheckIntervalSeconds <= 0 {
		return nil
	}

	refreshInterval := time.Duration(tuning.RefreshCheckIntervalSeconds) * time.Second

	expiryDeltaSeconds := float64(tuning.RefreshCheckIntervalSeconds) * tuning.RefreshExpiryDeltaFactor
	if lim := float64(math.MaxInt64 / time.Second); expiryDeltaSeconds > lim {
		expiryDeltaSeconds = lim
	}

	b := backoff.Build(
		backoff.Constant(refreshInterval),
		backoff.NonSliding,
	)
	err := retry.Wait(ctx, func(ctx context.Context) (bool, error) {
		rd.backend.Logger().Debug("running automatic credential refresh")

		err := rd.backend.data.AuthCode.Manager(rd.storage).ForEachAuthCodeKey(ctx, func(keyer persistence.AuthCodeKeyer) error {
			proc := &refreshProcess{
				backend:     rd.backend,
				storage:     rd.storage,
				keyer:       keyer,
				expiryDelta: time.Duration(expiryDeltaSeconds) * time.Second,
			}

			select {
			case pc <- proc:
			case <-ctx.Done():
			}

			return nil
		})
		if err != nil {
			return retry.Done(err)
		}

		return retry.Repeat(nil)
	}, retry.WithClock(rd.backend.clock), retry.WithBackoffFactory(b))
	if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		return nil
	}
	return err
}

func (b *backend) refreshCredToken(ctx context.Context, storage logical.Storage, keyer persistence.AuthCodeKeyer, expiryDelta time.Duration) (*persistence.AuthCodeEntry, error) {
	ctx = clockctx.WithClock(ctx, b.clock)

	var entry *persistence.AuthCodeEntry
	err := b.data.AuthCode.WithLock(keyer, func(ach *persistence.LockedAuthCodeHolder) error {
		acm := ach.Manager(storage)

		// In case someone else refreshed this token from under us, we'll re-request
		// it here with the lock acquired.
		candidate, err := acm.ReadAuthCodeEntry(ctx)
		switch {
		case err != nil || candidate == nil:
			return err
		case !candidate.TokenIssued() || b.tokenValid(candidate.Token.Token, expiryDelta) || candidate.RefreshToken == "":
			entry = candidate
			return nil
		}

		ops, put, err := b.getProviderOperations(ctx, storage, persistence.AuthServerName(candidate.AuthServerName), expiryDelta)
		if errmark.MarkedUser(err) {
			candidate.SetAuthServerError(ctx, errmark.MarkShort(err).Error())
		} else if err != nil {
			return err
		} else {
			defer put()

			// Refresh.
			refreshed, err := ops.RefreshToken(ctx, candidate.Token, provider.WithProviderOptions(candidate.ProviderOptions))

			if err != nil {
				msg := errmap.Wrap(errmark.MarkShort(err), "refresh failed").Error()
				if errmark.MarkedUser(err) {
					candidate.SetUserError(ctx, msg)
				} else {
					candidate.SetTransientError(ctx, msg)
				}
			} else {
				candidate.SetToken(ctx, refreshed)
			}
		}

		if err := acm.WriteAuthCodeEntry(ctx, candidate); err != nil {
			return err
		}

		entry = candidate
		return nil
	})
	return entry, err
}

func (b *backend) getRefreshCredToken(ctx context.Context, storage logical.Storage, keyer persistence.AuthCodeKeyer, expiryDelta time.Duration) (*persistence.AuthCodeEntry, error) {
	entry, err := b.data.AuthCode.Manager(storage).ReadAuthCodeEntry(ctx, keyer)
	switch {
	case err != nil:
		return nil, err
	case entry == nil:
		return nil, nil
	case !entry.TokenIssued() || b.tokenValid(entry.Token.Token, expiryDelta):
		return entry, nil
	default:
		// If we're on a standby node, forward to the active before
		// refreshing. This ensures we don't get rate limited by the token
		// issuer and limits the number of spurious tokens we get.
		if b.System().ReplicationState().HasState(consts.ReplicationDRSecondary|consts.ReplicationPerformanceStandby) ||
			(!b.System().LocalMount() && b.System().ReplicationState().HasState(consts.ReplicationPerformanceSecondary)) {
			return nil, logical.ErrReadOnly
		}

		return b.refreshCredToken(ctx, storage, keyer, expiryDelta)
	}
}

func (b *backend) storeExchangedToken(ctx context.Context, storage logical.Storage, keyer persistence.AuthCodeKeyer, exchangeKey string, tok *oauth2.Token) error {
	ctx = clockctx.WithClock(ctx, b.clock)

	err := b.data.AuthCode.WithLock(keyer, func(ach *persistence.LockedAuthCodeHolder) error {
		acm := ach.Manager(storage)

		entry, err := acm.ReadAuthCodeEntry(ctx)
		if err != nil || entry == nil {
			return err
		}

		if entry.ExchangedTokens == nil {
			// first time, make the map
			entry.ExchangedTokens = make(map[string]*oauth2.Token)
		} else {
			// remove every expired exchanged token while we're here
			for k, t := range entry.ExchangedTokens {
				if !b.tokenValid(t, defaultExpiryDelta) {
					delete(entry.ExchangedTokens, k)
				}
			}
		}
		entry.ExchangedTokens[exchangeKey] = tok

		if err := acm.WriteAuthCodeEntry(ctx, entry); err != nil {
			return err
		}

		return nil
	})
	return err
}

package interop

// JSONToken represents the JSON response of an access token request.
//
// It is different from an oauth2.Token, which is also serializable as JSON, but
// does not correspond to the response data.
type JSONToken struct {
	AccessToken  string `json:"access_token"`
	TokenType    string `json:"token_type"`
	ExpiresIn    int32  `json:"expires_in,omitempty"`
	RefreshToken string `json:"refresh_token,omitempty"`
	Scope        string `json:"scope,omitempty"`
}

// JSONError is the type of an error response.
type JSONError struct {
	Error            string `json:"error"`
	ErrorDescription string `json:"error_description,omitempty"`
	ErrorURI         string `json:"error_uri,omitempty"`
}

package clientctx

import (
	"bytes"
	"context"
	"io"
	"net/http"

	"golang.org/x/oauth2"
)

type roundTripper struct {
	http.RoundTripper
	fn func(req *http.Request) error
}

func (t *roundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	req = req.Clone(req.Context())
	if err := t.fn(req); err != nil {
		return nil, err
	}
	return t.RoundTripper.RoundTrip(req)
}

// WithUpdatedRequest returns a context that wraps the current OAuth2 HTTP
// client with a function that can amend a request in flight.
//
// The API provided by the OAuth2 package is not sufficient for some
// applications. For example, the OAuth2 package does not provide a way to
// specify multiple audiences or resources for a request per RFC 8693.
func WithUpdatedRequest(ctx context.Context, fn func(req *http.Request) error) context.Context {
	orig := oauth2.NewClient(ctx, nil)

	transport := orig.Transport
	if transport == nil {
		transport = http.DefaultTransport
	}

	upd := &http.Client{}
	*upd = *orig
	upd.Transport = &roundTripper{
		RoundTripper: transport,
		fn:           fn,
	}

	return context.WithValue(ctx, oauth2.HTTPClient, upd)
}

// WithUpdatedRequestBody returns a context that wraps the current OAuth2 HTTP
// client with a function that can amend the body of a request in flight.
func WithUpdatedRequestBody(ctx context.Context, fn func(body []byte) ([]byte, error)) context.Context {
	return WithUpdatedRequest(ctx, func(req *http.Request) (err error) {
		closed := false
		closer := req.Body
		defer func() {
			if closed {
				return
			}
			if cerr := closer.Close(); cerr != nil && err == nil {
				err = cerr
			}
		}()
		body, err := io.ReadAll(req.Body)
		if err != nil {
			return err
		}
		closed = true
		if err := closer.Close(); err != nil {
			return err
		}

		body, err = fn(body)
		if err != nil {
			return err
		}

		req.ContentLength = int64(len(body))
		req.Body = io.NopCloser(bytes.NewReader(body))
		req.GetBody = func() (io.ReadCloser, error) {
			return io.NopCloser(bytes.NewReader(body)), nil
		}
		return nil
	})
}

package semerr

import (
	"encoding/json"
	"errors"
	"net"
	"net/http"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/oauth2ext/interop"
	"github.com/puppetlabs/leg/errmap/pkg/errmark"
	"golang.org/x/oauth2"
)

type Error struct {
	Code        string
	Description string
	URI         string
}

func (e *Error) Error() string {
	msg := "server rejected request: " + e.Code
	if e.Description != "" {
		msg += ": " + e.Description
	}
	if e.URI != "" {
		msg += " (see " + e.URI + ")"
	}
	return msg
}

func IsCode(err error, code string) bool {
	var e *Error
	if !errors.As(err, &e) {
		return false
	}

	return e.Code == code
}

func RuleCode(code string) errmark.Rule {
	return errmark.RuleFunc(func(err error) bool {
		return IsCode(err, code)
	})
}

func Map(cerr error) error {
	if cerr == nil {
		return nil
	}

	// We consider any net.OpError to be temporary. E.g., a server might be down
	// and we need to try a refresh again later.
	var nerr *net.OpError
	if errors.As(cerr, &nerr) {
		return errmark.MarkTransient(cerr)
	}

	rerr, ok := cerr.(*oauth2.RetrieveError)
	if !ok {
		return cerr
	}

	switch rerr.Response.StatusCode {
	case http.StatusBadRequest, http.StatusUnauthorized, http.StatusForbidden:
	default:
		return rerr
	}

	var env interop.JSONError
	if json.Unmarshal(rerr.Body, &env) != nil {
		return rerr
	}

	return errmark.MarkUserIf(
		&Error{
			Code:        env.Error,
			Description: env.ErrorDescription,
			URI:         env.ErrorURI,
		},
		errmark.RuleAny(
			RuleCode("invalid_request"),
			RuleCode("invalid_client"),
			RuleCode("invalid_grant"),
			RuleCode("unauthorized_client"),
			RuleCode("unsupported_grant_type"),
			RuleCode("invalid_scope"),
		),
	)
}

package devicecode

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/openbao/openbao-plugin-secrets-oauthapp/v3/pkg/oauth2ext/interop"
	"golang.org/x/oauth2"
)

const (
	GrantType = "urn:ietf:params:oauth:grant-type:device_code"
)

type Auth struct {
	DeviceCode              string `json:"device_code"`
	UserCode                string `json:"user_code"`
	VerificationURI         string `json:"verification_uri"`
	VerificationURIComplete string `json:"verification_uri_complete,omitempty"`
	ExpiresIn               int32  `json:"expires_in"`
	Interval                int32  `json:"interval,omitempty"`
}

type Config struct {
	*oauth2.Config

	DeviceURL string
}

func (c *Config) DeviceCodeAuth(ctx context.Context) (*Auth, error) {
	v := url.Values{
		"client_id": {c.ClientID},
	}
	if len(c.Scopes) > 0 {
		v.Set("scope", strings.Join(c.Scopes, " "))
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.DeviceURL, strings.NewReader(v.Encode()))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("Accept", "application/json")

	resp, err := oauth2.NewClient(ctx, nil).Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	// This is the same restriction as used by Go's OAuth2 package for
	// consistency.
	reader := io.LimitReader(resp.Body, 1<<20)

	switch {
	case resp.StatusCode < 200 || resp.StatusCode >= 300:
		body, err := io.ReadAll(reader)
		if err != nil {
			return nil, fmt.Errorf("cannot fetch device code authorization: %w", err)
		}

		return nil, &oauth2.RetrieveError{
			Response: resp,
			Body:     body,
		}
	default:
		auth := &Auth{}
		if err := json.NewDecoder(reader).Decode(auth); err != nil {
			return nil, err
		}
		switch {
		case auth.DeviceCode == "":
			return nil, errors.New("server response missing device_code")
		case auth.UserCode == "":
			return nil, errors.New("server response missing user_code")
		case auth.VerificationURI == "":
			return nil, errors.New("server response missing verification_uri")
		case auth.ExpiresIn <= 0:
			return nil, errors.New("server response missing expires_in")
		}

		return auth, nil
	}
}

func (c *Config) DeviceCodeExchange(ctx context.Context, deviceCode string) (*oauth2.Token, error) {
	v := url.Values{
		"grant_type":  {GrantType},
		"client_id":   {c.ClientID},
		"device_code": {deviceCode},
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.Endpoint.TokenURL, strings.NewReader(v.Encode()))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("Accept", "application/json")

	resp, err := oauth2.NewClient(ctx, nil).Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	// This is the same restriction as used by Go's OAuth2 package for
	// consistency.
	reader := io.LimitReader(resp.Body, 1<<20)

	body, err := io.ReadAll(reader)
	if err != nil {
		return nil, fmt.Errorf("cannot fetch device code authorization: %w", err)
	}

	switch {
	case resp.StatusCode < 200 || resp.StatusCode >= 300:
		return nil, &oauth2.RetrieveError{
			Response: resp,
			Body:     body,
		}
	default:
		var base interop.JSONToken
		if err := json.Unmarshal(body, &base); err != nil {
			return nil, err
		}
		if base.AccessToken == "" {
			return nil, errors.New("server response missing access_token")
		}

		tok := &oauth2.Token{
			AccessToken:  [REDACTED],
			TokenType:    base.TokenType,
			RefreshToken: [REDACTED],
		}
		if base.ExpiresIn != 0 {
			tok.Expiry = time.Now().Add(time.Duration(base.ExpiresIn) * time.Second)
		}

		// The Go library does not check for errors here. If there is one, it
		// will be ignored.
		var extra map[string]interface{}
		_ = json.Unmarshal(body, &extra)

		if extra != nil {
			tok = tok.WithExtra(extra)
		}

		return tok, nil
	}
}
